$ErrorActionPreference='Stop';$root=$PSScriptRoot;$name='Trajectory-ObservableInformation-Step4-20261027'
function Read-Json($n){$p=Join-Path $root $n;if(Test-Path -LiteralPath $p){Get-Content -LiteralPath $p -Raw -Encoding UTF8|ConvertFrom-Json}else{$null}}
$procs=@(Get-CimInstance Win32_Process -Filter "Name='python.exe'"|Where-Object{$_.CommandLine -and $_.CommandLine.IndexOf($root,[StringComparison]::OrdinalIgnoreCase) -ge 0}|ForEach-Object{[pscustomobject]@{pid=$_.ProcessId;parent=$_.ParentProcessId;created=$_.CreationDate.ToString('o');commandline=$_.CommandLine}})
$parents=@($procs.parent|Sort-Object -Unique|ForEach-Object{Get-CimInstance Win32_Process -Filter "ProcessId=$_"|Select-Object ProcessId,ParentProcessId,Name,CommandLine})
$task=Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue;$triggers=$null
if($task){[xml]$xml=Export-ScheduledTask -TaskName $name;$triggers=@($xml.SelectNodes('/*[local-name()="Task"]/*[local-name()="Triggers"]/*')).Count}
$selections=@();foreach($seed in @(42,43,44)){$d=Read-Json "selections/seed$seed/SELECTION.json";if($d){$selections+=[pscustomobject]@{seed=$seed;science_assignments=$d.scientific_assignment_problems;calibration_primary=$d.primary.calibration_valid;supported_primary=$d.primary.supported_tracks;done=(Test-Path -LiteralPath (Join-Path $root "selections/seed$seed/done.json"))}}}
[pscustomobject]@{at=(Get-Date).ToString('o');task=$name;task_state=if($task){[string]$task.State}else{$null};triggers=$triggers;processes=$procs;parents=$parents;worker=(Read-Json 'worker_state.json');exit=(Read-Json 'exit_status.json');stage=(Read-Json 'progress.json');child=(Read-Json 'current_child.json');selections=$selections;result=(Read-Json 'RESULT.json');stderr_bytes=if(Test-Path -LiteralPath (Join-Path $root 'worker.stderr.log')){(Get-Item -LiteralPath (Join-Path $root 'worker.stderr.log')).Length}else{$null}}|ConvertTo-Json -Depth 30
